import{C as l,o as d,c as r,j as e,a as t,E as h,a3 as n,k as s,g as a}from"./chunks/framework.BmyRW8Ui.js";const p={tabindex:"0"},u=["href"],c=["href"],y=JSON.parse('{"title":"Poulpy in 3D","description":"","frontmatter":{},"headers":[],"relativePath":"poulpy-3d.md","filePath":"poulpy-3d.md"}'),g={name:"poulpy-3d.md"},w=Object.assign(g,{setup(m){return(b,o)=>{const i=l("Poulpy3d",!0);return d(),r("div",null,[o[4]||(o[4]=e("h1",{id:"poulpy-in-3d",tabindex:"-1"},[t("Poulpy in 3D "),e("a",{class:"header-anchor",href:"#poulpy-in-3d","aria-label":'Permalink to "Poulpy in 3D"'},"​")],-1)),o[5]||(o[5]=e("p",null,[t("The plush as a solid you can turn around: a bubble of a head tucked into eight puffy arms, drawn with flat cartoon shading. One file, "),e("a",{href:"https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/model.mjs",target:"_blank",rel:"noreferrer"},[e("code",null,"design/poulpy-3d/model.mjs")]),t(", describes his shape; this page draws it live and "),e("a",{href:"https://github.com/tkint/coach-poulpy/blob/main/design/build-poulpy-3d.mjs",target:"_blank",rel:"noreferrer"},[e("code",null,"design/build-poulpy-3d.mjs")]),t(" writes it as glTF files. He is not in the apps yet: this is the reference to build from.")],-1)),h(i),o[6]||(o[6]=n('<h2 id="the-rules-of-the-shape" tabindex="-1">The rules of the shape <a class="header-anchor" href="#the-rules-of-the-shape" aria-label="Permalink to &quot;The rules of the shape&quot;">​</a></h2><p>These were settled with the owner on the first model; the reasons are in <a href="/pr-preview/pr-409/docs/brand-decisions#_14-poulpy-in-3d-a-bubble-plush-in-flat-shading">Brand decisions</a>.</p><ul><li><strong>Chibi, never realistic.</strong> A big round head, big eyes, short arms. The face is the 2D drawing&#39;s, pressed onto the head, so every <a href="/pr-preview/pr-409/drawings">drawing</a> and the model show the same Poulpy.</li><li><strong>The head is tucked in.</strong> It sinks into the arms, which wrap around its base, instead of resting on top of them.</li><li><strong>Eight arms, always down.</strong> They lie on the floor as on the plush; a mood shows on his face and in his colour, never by lifting an arm.</li><li><strong>The other side is underneath.</strong> Each arm is one smooth shape, the side&#39;s colour on top and the other side&#39;s colour below a low line, with no ridge or shelf between them. The base of the head is cut at the same height, so the whole underside is one colour: ember under the blue side, blue under the ember side.</li><li><strong>Flat, like a drawing.</strong> Plain token colours, one soft shadow band and one faint gleam. No gloss, no reflections, no fabric texture.</li><li><strong>The light belongs to the room.</strong> It comes from the viewer&#39;s upper left and stays there: the shade and the gleam slide over Poulpy as he turns, they are never painted on him.</li><li><strong>The outline is optional and off by default.</strong> It is there for small sizes or busy backgrounds.</li></ul><h2 id="using-the-model" tabindex="-1">Using the model <a class="header-anchor" href="#using-the-model" aria-label="Permalink to &quot;Using the model&quot;">​</a></h2>',4)),e("table",p,[o[3]||(o[3]=e("thead",null,[e("tr",null,[e("th",null,"File"),e("th",null,"What it is")])],-1)),e("tbody",null,[e("tr",null,[e("td",null,[e("a",{href:s(a)("/design/poulpy-3d/poulpy_blue.glb"),download:""},"poulpy_blue.glb",8,u)]),o[0]||(o[0]=e("td",null,"The blue, smiling side, as binary glTF",-1))]),e("tr",null,[e("td",null,[e("a",{href:s(a)("/design/poulpy-3d/poulpy_ember.glb"),download:""},"poulpy_ember.glb",8,c)]),o[1]||(o[1]=e("td",null,"The ember, grumpy side, as binary glTF",-1))]),o[2]||(o[2]=e("tr",null,[e("td",null,[e("a",{href:"https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/model.mjs",target:"_blank",rel:"noreferrer"},[e("code",null,"design/poulpy-3d/model.mjs")])]),e("td",null,"The shape itself, as plain JavaScript with no dependency")],-1))])]),o[7]||(o[7]=n('<p>The glTF files open in any 3D tool or engine. Poulpy stands on the floor (y = 0, y up) and faces +z; his head is about one unit from centre to edge. Each part is its own named mesh (<code>head</code>, <code>head_lining</code>, <code>arm_1</code> to <code>arm_8</code> and their <code>_lining</code>, <code>eye_left</code>, <code>eye_left_shine</code>, <code>cheek_left</code>, <code>mouth</code>, <code>gleam</code>, plus <code>brow_left</code> and <code>brow_right</code> on the ember side), so a part can be recoloured, hidden or animated on its own.</p><p>A glTF file only carries shapes and plain matte colours. The look is the renderer&#39;s job, and <code>LOOK</code> in <code>model.mjs</code> gives its numbers: the light&#39;s direction as the viewer sees it, the shadow band&#39;s strength, where the gleam sits, and the outline&#39;s width and tint. A renderer that wants the gleam to follow the light drops the <code>gleam</code> mesh from the file and asks <code>gleamPatch(direction)</code> for a new one whenever Poulpy or the camera turns. <a href="https://github.com/tkint/coach-poulpy/blob/main/site/.vitepress/theme/poulpy3dScene.ts" target="_blank" rel="noreferrer"><code>poulpy3dScene.ts</code></a>, which draws the preview above with three.js, is the worked example.</p><h2 id="changing-the-design" tabindex="-1">Changing the design <a class="header-anchor" href="#changing-the-design" aria-label="Permalink to &quot;Changing the design&quot;">​</a></h2><p>Everything that defines him is at the top of <code>model.mjs</code>, in three plainly named objects:</p><ul><li><code>SHAPE</code>: the size of the head and how deep it sits, the number, size and reach of the arms, the height of the line between the two colours, and where the face sits.</li><li><code>FACES</code>: the eyes, cheeks, mouth and brows of each side, in the same units as the 2D drawings of <code>design/build-poulpy.mjs</code>.</li><li><code>LOOK</code>: the light, the shadow band, the gleam and the outline.</li></ul><p>His colours are the <code>color.poulpy</code> tokens of <a href="https://github.com/tkint/coach-poulpy/blob/main/design/tokens.json" target="_blank" rel="noreferrer"><code>design/tokens.json</code></a>, never written into the model.</p><p>Edit, then regenerate and look at this page (<code>npm run dev</code> in <code>site/</code>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-poulpy-3d.mjs</span></span></code></pre></div><p>CI runs it with <code>--check</code> and fails when the committed glTF files no longer match <code>model.mjs</code>. A new mood or pose in 3D starts as a new entry in <code>FACES</code>, or a new part in <code>buildPoulpy3d</code>, and follows the <a href="/pr-preview/pr-409/docs/brand#character-rules">brand rules</a> like any drawing.</p>',9))])}}});export{y as __pageData,w as default};
